  "claims": [
    {
      "id": "r:1832875650",
      "kind": "approach",
      "harm": "Configuring maxfeerate as a node-wide option instead of wallet-only bleeds wallet settings into node RPCs and removes useful mempool RPC options",
      "quote": "I don't think that wallet configurations should bleed into how the node RPCs function. Instead, the interaction there should be for wallet to pass it as a param to BroadcastTransaction when the it submits a tx to the node.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:1900699310",
        "rc:1467012789",
        "c:1911091517"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:1911091517",
      "settled_by_quote": "Made maxfeerate wallet option"
    },
    {
      "id": "rc:1469372132",
      "kind": "correctness",
      "harm": "Removing the check for max_fee resulting in feerate below relayMinFee permits users to set unworkable maxtxfee values without startup warnings",
      "quote": "I don't think we should remove this check for setting a max_fee that results in fee rates less than the relayMinFee.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:1472785028",
        "rc:1472858661",
        "rc:1477791006"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:1477791006",
      "settled_by_quote": "I agree with @josibake suggestion and added a commit that performs the same check in wallet initialization as before."
    },
    {
      "id": "rc:1473275731",
      "kind": "interface",
      "harm": "Replacing descriptive error messages with a generic string obscures which limit (maxtxfee or maxfeerate) was hit",
      "quote": "It isn’t clear to me why we would first ship a less descriptive new error message in this PR and then immediately fix it in a follow-up.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:1477810958"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:1477810958",
      "settled_by_quote": "However I agree with your comment, I have now added a commit that also checks the fee rate limit in BroadcastTransaction, and changed how sendrawtransaction is implemented, and updated the MAX_FEE_EXCEEDED transaction error type message."
    },
    {
      "id": "c:3898336639",
      "kind": "correctness",
      "harm": "Overestimating virtual size using nBytes causes the wallet to create transactions that later fail the maxfeerate check at broadcast time and mark inputs untrusted",
      "quote": "The issue is that in createTransactionInternal, I was using nBytes to calculate the fee rate. This is incorrect because nBytes is the virtual size calculated using CalculateMaximumSignedTx. There are cases where nBytes is overestimated... But when we broadcast the tx, BroadcastTransaction uses the actual transaction vsize and fee... it will turn out to be slightly higher than maxfeerate",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:3898336639"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:3898336639",
      "settled_by_quote": "I fixed this by using GetVirtualTransactionSize to compute the fee rate."
    },
    {
      "id": "c:5441203296",
      "kind": "correctness",
      "harm": "sendall ignores bump fees for unconfirmed inputs when evaluating maxfeerate, causing transaction creation to succeed while broadcast fails silently",
      "quote": "sendall's creation-time -maxfeerate check ignores bump fees for unconfirmed inputs, while the broadcast-time check in BroadcastTransaction includes them. When fee_rate is set exactly equal to -maxfeerate and the wallet spends unconfirmed inputs with positive bump fees, the creation check passes... but the broadcast check fails",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:5655683492"
      ],
      "fix_pushed": true,
      "settled_by_id": "r:5213483629",
      "settled_by_quote": "ACK f69e56bc1c43ca2bebd4d733bce1afc8de8f58b9"
    }
  ],
